// scope_axil ΓÇö AXI4-Lite slave front-end for the scope's native CSR bus (issue #11).
//
// A THIN protocol adapter: zero scope logic. Maps the five AXI4-Lite channels onto the native
// CSR bus (word-addressed, combinational read, single-cycle strobes). One transaction at a time
// through a tiny FSM ΓÇö AXI4-Lite does not require concurrent read+write, and serializing keeps
// the single-cycle `csr_write`/`csr_read` strobes (and the BUF_DATA pop-on-read side effect)
// exactly once per transaction.
//
//   * Address: AXI byte address; low 2 bits ignored; ADDR[9:2] is the CSR word index.
//   * Write: accepted only when BOTH AW and W are valid (joint accept), so any AW/W arrival
//     order works. One `csr_write` strobe on the accept cycle, then BRESP=OKAY.
//   * Read: on AR handshake, one `csr_read` strobe; the combinational `csr_rdata` is latched
//     that cycle (so the BUF_DATA read pointer may advance underneath us), then RVALID/RDATA.
//   * Responses are always OKAY. Writes to read-only registers are silently ignored inside
//     scope_csr (no SLVERR in v1); config writes while capturing set the sticky cfg_err bit ΓÇö
//     the adapter is oblivious. Documented in docs/INTERFACES.md.
//   * Write has priority over read when both are offered in IDLE (arbitrary, documented).
//
// Clock-domain contract: runs in scope_csr's clock domain (`clk`, capture domain) for
// XPORT="CSR"; host-side CDC is the integrating fabric's problem. See docs/INTERFACES.md.

module scope_axil (
    input  logic        clk,
    input  logic        rst,          // synchronous, active high

    // AXI4-Lite slave (32-bit)
    input  logic [9:0]  awaddr,       // byte address; [9:2] = CSR word
    input  logic        awvalid,
    output logic        awready,
    input  logic [31:0] wdata,
    input  logic [3:0]  wstrb,        // accepted, not enforced (RMW is not a v1 CSR feature)
    input  logic        wvalid,
    output logic        wready,
    output logic [1:0]  bresp,
    output logic        bvalid,
    input  logic        bready,
    input  logic [9:0]  araddr,
    input  logic        arvalid,
    output logic        arready,
    output logic [31:0] rdata,
    output logic [1:0]  rresp,
    output logic        rvalid,
    input  logic        rready,

    // native CSR bus master
    output logic [7:0]  csr_addr,
    output logic [31:0] csr_wdata,
    output logic        csr_write,
    output logic        csr_read,
    input  logic [31:0] csr_rdata
);

  localparam logic [1:0] RESP_OKAY = 2'b00;

  typedef enum logic [1:0] { S_IDLE, S_WRESP, S_RRESP } state_e;
  state_e st;

  logic [31:0] rdata_q;

  // Combinational native-bus strobes: asserted only in IDLE on an accepted transaction.
  wire do_write = (st == S_IDLE) && awvalid && wvalid;
  wire do_read  = (st == S_IDLE) && !do_write && arvalid;  // write has priority

  assign csr_write = do_write;
  assign csr_read  = do_read;
  assign csr_addr  = do_write ? awaddr[9:2] : araddr[9:2];
  assign csr_wdata = wdata;

  // Channel readies / valids
  assign awready = do_write;
  assign wready  = do_write;
  assign arready = do_read;
  assign bresp   = RESP_OKAY;
  assign rresp   = RESP_OKAY;
  assign bvalid  = (st == S_WRESP);
  assign rvalid  = (st == S_RRESP);
  assign rdata   = rdata_q;

  always_ff @(posedge clk) begin
    if (rst) begin
      st      <= S_IDLE;
      rdata_q <= '0;
    end else begin
      unique case (st)
        S_IDLE: begin
          if (do_write)     st <= S_WRESP;
          else if (do_read) begin
            rdata_q <= csr_rdata;   // latch the combinational read (pointer may advance next cycle)
            st      <= S_RRESP;
          end
        end
        S_WRESP: if (bready) st <= S_IDLE;
        S_RRESP: if (rready) st <= S_IDLE;
        default: st <= S_IDLE;
      endcase
    end
  end

  wire _unused = &{1'b0, wstrb, awaddr[1:0], araddr[1:0]};

endmodule
// prim_ram_1r1w ΓÇö simple-dual-port RAM, 1 write + 1 read port (vendored fpgapa-prim primitive).
//
// What it is: one synchronous write port and one synchronous read port on a shared clock,
// 1-cycle read latency (`rd_data` valid the cycle after `rd_en` samples `rd_addr`), inferred
// block RAM. This is the ONLY memory-inference module in the design (tracker rule 2).
//
// Contract / POLICY (load-bearing ΓÇö asserted executable in sim/tb_prim_ram.sv):
//   * Read-during-write returns OLD DATA: when `wr_en && rd_en && wr_addr == rd_addr` in the
//     same cycle, `rd_data` delivers the PRE-write content of that location. Every consumer
//     in fpga-scope (capture buffer, FIFOs) assumes this policy.
//   * `rd_data` holds its last value while `rd_en` is low.
//   * The array has no reset and no initial value; contents before first write are undefined.
//
// Policy decisions: plain always_ff array, separate write and read processes, no bypass
// logic, no reset on the array ΓÇö written this way so Verilator simulates it and Quartus,
// Vivado, and Yosys all infer block RAM from the same source. No vendor primitives.
module prim_ram_1r1w #(
    parameter int unsigned WIDTH      = 8,
    parameter int unsigned DEPTH_LOG2 = 8
) (
    input  logic                  clk,
    input  logic                  wr_en,
    input  logic [DEPTH_LOG2-1:0] wr_addr,
    input  logic [WIDTH-1:0]      wr_data,
    input  logic                  rd_en,
    input  logic [DEPTH_LOG2-1:0] rd_addr,
    output logic [WIDTH-1:0]      rd_data
);

  localparam int unsigned DEPTH = 1 << DEPTH_LOG2;

  logic [WIDTH-1:0] mem[DEPTH];

  always_ff @(posedge clk) begin
    if (wr_en) mem[wr_addr] <= wr_data;
  end

  // Separate read process; nonblocking write above guarantees the "old data" policy in
  // simulation, and the separate-process shape is what all four target flows map to a
  // block-RAM read port.
  always_ff @(posedge clk) begin
    if (rd_en) rd_data <= mem[rd_addr];
  end

endmodule
// scope_top ΓÇö the assembled embedded logic analyzer: trigger + core + CSR + drain + transport.
//
// Frozen host contract: docs/INTERFACES.md (parameters, ports, CSR map, frame format).
// Architecture: docs/DESIGN.md. Block wiring (PLAN.md ┬º5):
//
//   probe ΓöÇΓû║[scope_trigger]ΓöÇΓöÇtrigΓöÇΓöÇΓû║ΓöÉ
//   probe ΓöÇΓû║(sample_o, RLE stub)ΓöÇΓöÇΓû║ [scope_core]  ΓùäΓöÇΓöÇ arm/config ΓöÇΓöÇ [scope_csr]
//                                        Γöé rd ports                     Γû▓ native CSR bus
//                                     capture domain (clk)          [servicer FSM]
//   ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ prim_fifo_async x2 (cmd in / rsp out ΓÇö THE single CDC) ΓòÉΓòÉΓò¬ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
//                                     transport domain (xclk)       [scope_drain]
//                                                     [scope_uart | raw stream | (CSR mode)]
//
// Policy decisions:
//   * RLE stage (issue #9): with RLE_EN the trigger's aligned sample_o is run-length-encoded
//     by scope_rle into STORE_W=PROBE_W+1 {is_count,value} words; the core/csr/drain store and
//     drain WORDS, the trigger is re-aligned onto its (flushed) trigger word, and the host
//     reorders in the word domain then rle_decodes (rle_flag=1 in the DRAIN header). With
//     RLE_EN=0 the path is sample_o at PROBE_W, sample_valid tied 1 (PLAN.md ┬º6.1) ΓÇö the
//     datapath is byte-identical to the pre-#9 design (STORE_W==PROBE_W).
//   * Exactly ONE CDC (tracker rule 7): the cmd/rsp async-FIFO pair. It stays even when
//     xclk == clk (no bypass in v1 ΓÇö correctness over area). The capture/write path never
//     sees transport back-pressure (tracker rule 1): the servicer only ever performs CSR
//     ops, which cannot stall the sample path.
//   * Servicer discipline: pop one cmd, execute one 1-cycle CSR strobe (side effects like
//     BUF_DATA pops must strobe exactly once), push one response, repeat. Combined with
//     the drain's one-outstanding rule the FIFOs can never overflow (formal (d)).
//   * XPORT selects the transport at elaboration: "UART" = scope_uart on uart_rx/uart_tx
//     (a small prim_fifo_sync absorbs rx bursts; UART has no flow control); "STREAM" =
//     raw rx_*/tx_* byte stream; "CSR" = no byte transport at all ΓÇö the external native
//     CSR port (ext_csr_*, a v1 interface ADDITION for the #11 front-ends) owns the CSR
//     bus, and BUF_CTRL/BUF_DATA/WIN_SEL/WIN_META are the drain path.
//   * run (sequencer enable) = state==ARMED; trig_ext_i ORs into the trigger; trig_ext_o
//     never echoes trig_ext_i (no cross-instance loops). All identity comes from the
//     ID_VALUE parameter ΓÇö no singleton state; two instances in one design work.
module scope_top #(
    parameter int unsigned PROBE_W    = 32,       // 1..512
    parameter int unsigned DEPTH_LOG2 = 8,        // 8..15
    parameter int unsigned NUM_CMP    = 4,
    parameter int unsigned SEQ_STAGES = 4,
    parameter bit          RLE_EN     = 1'b0,     // RLE lands in issue #9 (bypass stub now)
    parameter int unsigned TS_W       = 48,
    parameter              XPORT      = "UART",   // "UART" | "STREAM" | "CSR" (untyped: yosys)
    parameter int unsigned UART_DIV   = 16,       // xclk cycles per bit
    parameter logic [31:0] ID_VALUE   = 32'h0     // user tag, PING response
) (
    // capture domain
    input  logic               clk,
    input  logic               rst,        // synchronous, active high
    input  logic [PROBE_W-1:0] probe,
    input  logic               trig_ext_i,
    output logic               trig_ext_o,

    // transport domain (may be the same clock as clk)
    input  logic               xclk,
    input  logic               xrst,       // assert together with rst (async FIFO contract)

    // byte stream (XPORT=="STREAM"; tied off otherwise)
    input  logic [7:0]         rx_data,
    input  logic               rx_valid,
    output logic               rx_ready,
    output logic [7:0]         tx_data,
    output logic               tx_valid,
    input  logic               tx_ready,

    // UART pins (XPORT=="UART"; tied off otherwise)
    input  logic               uart_rx,
    output logic               uart_tx,

    // status
    output logic               armed,
    output logic               triggered,

    // external native CSR master (XPORT=="CSR" only ΓÇö v1 addendum for the #11 front-ends)
    input  logic [7:0]         ext_csr_addr,
    input  logic [31:0]        ext_csr_wdata,
    input  logic               ext_csr_write,
    input  logic               ext_csr_read,
    output logic [31:0]        ext_csr_rdata
);

  // ------------------------------ capture domain --------------------------------------

  // Stored-word width: with RLE the core/csr/drain store {is_count,value} words (PROBE_W+1);
  // without RLE it is the raw probe width (datapath byte-identical to the pre-#9 design).
  localparam int unsigned STORE_W = RLE_EN ? (PROBE_W + 1) : PROBE_W;

  // native CSR bus (master = servicer, or ext_csr_* in CSR mode)
  logic [7:0] csr_addr;
  logic [31:0] csr_wdata;
  logic csr_write, csr_read;
  logic [31:0] csr_rdata;

  logic arm, disarm, force_trig;
  logic [DEPTH_LOG2-1:0] pretrig;
  logic [7:0] windows;
  logic rle_enable;
  logic [23:0] decim;              // SMPL_CTRL (issue #17/#20)
  logic qual_en;
  logic [1:0] qual_sel;
  logic [2:0] state;
  logic wrapped, cfg_err;
  logic [7:0] windows_done;
  logic [DEPTH_LOG2-1:0] trig_index;
  logic [TS_W-1:0] ts, ts_at_trig;
  logic [DEPTH_LOG2-1:0] buf_rd_addr;
  logic [STORE_W-1:0] buf_rd_data;
  logic [7:0] win_rd_addr;
  logic [DEPTH_LOG2:0] win_rd_data;
  logic [NUM_CMP*PROBE_W-1:0] cmp_mask, cmp_value, cmp_edge_mask, cmp_edge_pol;
  logic [31:0] trig_combine;
  logic [SEQ_STAGES*32-1:0] seq_cnt;

  logic trig;
  logic [PROBE_W-1:0] sample_o;
  logic [NUM_CMP-1:0] cmp_hit;

  scope_trigger #(
      .PROBE_W   (PROBE_W),
      .NUM_CMP   (NUM_CMP),
      .SEQ_STAGES(SEQ_STAGES)
  ) u_trigger (
      .clk          (clk),
      .rst          (rst),
      .probe        (probe),
      .run          (state == 3'(scope_pkg::SCOPE_ST_ARMED)),
      .force_trig   (force_trig),
      .trig_ext_i   (trig_ext_i),
      .cmp_mask     (cmp_mask),
      .cmp_value    (cmp_value),
      .cmp_edge_mask(cmp_edge_mask),
      .cmp_edge_pol (cmp_edge_pol),
      .trig_combine (trig_combine),
      .seq_cnt      (seq_cnt),
      .trig         (trig),
      .trig_ext_o   (trig_ext_o),
      .sample_o     (sample_o),
      .cmp_hit      (cmp_hit)
  );

# scope_top utilization sweep (issue #12)

Reproducible resource numbers for `scope_top` across **PROBE_W Γêê {32, 128, 512} ├ù DEPTH_LOG2 Γêê
{8, 12, 15}** (RLE_EN=1, so STORE_W = PROBE_W+1), on three flows. The point of the design-doc ┬º9
target: the capture buffer should cost **Γëñ ~1.2├ù the raw BRAM** (DEPTH ├ù STORE_W bits) plus small
control logic.

| Flow | Tool | Part | Script | Status here |
|---|---|---|---|---|
| Quartus | Quartus-Pro 26.1 | Agilex 3 `A3CY100BM16AE7S` | `quartus_sweep.sh` | **runnable** (docker image present) |
| Vivado | Vivado | any 7-series/UltraScale (synth-only OK) | `vivado_sweep.tcl`* | documented; Vivado not installed here |
| Yosys+nextpnr | OSS CAD Suite | ECP5 (`--45k`; note if 512├ù2┬╣Γü╡ overflows) | `ecp5_sweep.sh`* | documented; run where the part fits |

\* The Vivado/nextpnr scripts mirror `quartus_sweep.sh`: elaborate `rtl/scope_top.sv` (+ prims, +
`scope_pkg`) with the two parameters overridden per config, run synth (+ place for nextpnr), and
scrape LUT/FF/BRAM. Only the Quartus flow is exercised in this environment; the demo build's
full-fit anchor (PROBE_W=32, DEPTH_LOG2=12: 8 M20K = 4096├ù33 = exactly the raw buffer) is in
`../axc3000/README.md`.

Run:
```bash
bash fpga/util_sweep/quartus_sweep.sh                 # full 3x3 -> utilization_quartus.md
PWS="32" DLS="8 12 15" bash fpga/util_sweep/quartus_sweep.sh   # one width, all depths
```
